select jsonb_build_object(
'observed_at',clock_timestamp(),
'migrations',(select count(*) from supabase_migrations.schema_migrations),
'bot',(select jsonb_build_object('bot_id',bot_id,'mode',mode,'enabled',enabled) from telegram_private.transport_bots where bot_id='100525277498990'),
'events',(select jsonb_agg(jsonb_build_object('id',id,'state',state,'attempts',attempts,'delivery_attempts',delivery_attempts,'error_code',error_code,'has_input',payload_ciphertext is not null,'has_output',result_ciphertext is not null,'lease_live',lease_until>clock_timestamp()) order by sequence) from telegram_private.transport_events where bot_id='100525277498990'),
'subjects',(select jsonb_agg(jsonb_build_object('user_id',p.user_id,'transactions',(select count(*) from finance.transactions where user_id=p.user_id),'entries',(select count(*) from finance.transaction_entries where user_id=p.user_id),'events',(select count(*) from finance.transaction_events where user_id=p.user_id),'drafts',(select count(*) from telegram_private.drafts where user_id=p.user_id),'confirmations',(select count(*) from telegram_private.confirmations where user_id=p.user_id),'links',(select count(*) from telegram_private.links where user_id=p.user_id),'accounts',(select jsonb_agg(jsonb_build_object('id',a.id,'currency',a.currency_code,'balance_minor',((a.opening_balance+coalesce((select sum(e.signed_amount) from finance.transaction_entries e join finance.transactions t on t.id=e.transaction_id and t.user_id=e.user_id where e.user_id=a.user_id and e.account_id=a.id and t.status='posted'),0))*100)::numeric(20,0)::text)) from finance.accounts a where a.user_id=p.user_id)) order by p.user_id) from finance.profiles p where p.user_id in ('5efbe31b-667d-40f5-a09d-a7b99f8e0851','c9f02a79-5cff-4b7c-b062-61662f376620')),
'functions',(select jsonb_agg(jsonb_build_object('oid',p.oid,'owner',p.proowner,'acl',p.proacl,'definer',p.prosecdef,'config',p.proconfig,'signature',p.oid::regprocedure::text,'source',md5(p.prosrc)) order by p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('api','finance','ops','telegram_private')),
'unsafe_tenant_tables',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('finance','ops','telegram_private') and c.relkind='r' and c.relname<>'currencies' and (not c.relrowsecurity or not c.relforcerowsecurity))
) as audit;